import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Import / Export and Multi-File Programs","description":"","frontmatter":{"title":"Import / Export and Multi-File Programs","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed — modules are evaluated environments."},"headers":[],"relativePath":"handl/project/adrs/0056-import-export-and-multi-file-programs.md","filePath":"vendored/handl/project/adrs/0056-import-export-and-multi-file-programs.md"}`),a={name:`handl/project/adrs/0056-import-export-and-multi-file-programs.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0056-import-export-and-multi-file-programs" tabindex="-1">ADR-0056: Import / Export and Multi-File Programs <a class="header-anchor" href="#adr-0056-import-export-and-multi-file-programs" aria-label="Permalink to “ADR-0056: Import / Export and Multi-File Programs”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>A module is an environment value</strong> — evaluating a file produces the environment it defines.</li><li><strong><code>import</code> resolves source and caches the resulting environment</strong> (resolve → evaluate under the module <code>Language</code> → cache).</li><li><strong><code>export</code> defines a module&#39;s public surface</strong>; it is not a visibility keyword on individual bindings.</li><li><strong><code>field-access</code> is the module access mechanism</strong> — <code>module.name</code> reads the environment value.</li><li><strong>Import capability is a policy boundary</strong>, not a language concept: the host decides what may be imported.</li><li><strong>The stdlib becomes <code>.hnl</code> files</strong> evaluated into environments.</li><li><strong>The runtime exposes environments as values</strong>, so modules are inspectable and composable.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p><code>import</code>/<code>export</code> were <code>Foreign</code> host calls, so multi-file programs were a special mechanism outside the language and the stdlib could not be <code>.hnl</code>. Evaluated environments make a file an ordinary value and import a lookup.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep import/export as <code>Foreign</code></strong> — that is the special path this removes.</li><li><strong>Per-binding visibility</strong> — the export surface is the unit.</li><li><strong>A separate stdlib loader</strong> — the stdlib is <code>.hnl</code> like user code.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Modules are values; import is resolve + evaluate + cache.</li><li>The host controls import policy at the boundary.</li><li>The stdlib shares the module mechanism.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>handl-runtime/</code> — environment values, import resolver.</li><li><code>kit-prelude-lang/</code> — the <code>.hnl</code> stdlib.</li><li>Multi-file tests in <code>handl-runtime/tests/</code>.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Environment values, import resolution, export surface and the loader: +<a href="./../design/0056-import-export-and-multi-file-programs.html"><code>design/0056-import-export-and-multi-file-programs.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};